// === Tab: mySketch ===
let palettes = [
	['#fcab30', '#ff626a', '#4C1E4F', '#496ddb', '#FFC4EB'],
	['#4c1e4f', '#07beb8', '#fee1c7', '#fb7232','#f44174'],
	['#f75c03', '#d90368', '#e5beed', '#820263', '#291720', '#04a777']
]
let grid
let m 
let needRedrawSquares = false
let paletteIndex = 0

function setup() {
	createCanvas(windowWidth, windowHeight);
	m = max(width, height) * 0.95

	palettes = shuffle(palettes)
	grid = new Grid({ size: m, palette: palettes[paletteIndex % palettes.length], steps: floor(random(25, 50)) })
	grid.makeSquares()

	background(20)
}

function draw() {
	translate((width - m) / 2, (height - m) / 2)
	if (needRedrawSquares) {
		grid.drawSquares()
		needRedrawSquares = false
	}
	let done = grid.drawSquaresAnimate(millis())
	if (done) noLoop()
}

function mouseClicked() {
	clear()
	paletteIndex++
	grid.restart({ palette: palettes[paletteIndex % palettes.length], steps: floor(random(25, 50)) })
	loop()
}

function windowResized() {
	resizeCanvas(windowWidth, windowHeight)
	m = max(width, height) * 0.95
	grid.resize(m)
	clear()
	background(20)
	if (!isLooping()) {
		grid.drawSquares()
	} else {
		needRedrawSquares = true 	
	}
}

// === Tab: grid ===

class Grid {
	constructor({
		steps = 30, 
		size = window.innerWidth,
		palette,
		gap = 3
	} = {}) {
		this.gap = gap 
		this.size = size 
		this._steps = steps 
		this.palette = palette ?? ['#2a2a2a', '#ababab', '#efefef']
		this.cellSize = this.size / this._steps

		this.baseCells = []
		this.squares = [] 
		this.growing = []

		this.animateIndex = 0 
		this.addPerSecond = this._steps
		this.addPerSecondCurrent = this.addPerSecond
		this.lastTime = null 
		this.lastAdd = 0 
	}

	restart({ steps, palette }) {
		if (steps) this._steps = steps 
		if (palette) this.palette = palette 
		this.cellSize = this.size / this._steps 
		this.resetAnimation()
		this.makeSquares()
	}

	resize(newSize) {
		let oldSize = this.size 
		this.size = newSize
		this.cellSize = this.size / this._steps
		this.baseCells.forEach((row) => {
			row.forEach((cell) => {
				cell.x = map(cell.x, 0, oldSize, 0, newSize) 
				cell.y = map(cell.y, 0, oldSize, 0, newSize)
			})
		})

		this.squares.forEach((sqr) => {
			sqr.x = map(sqr.x, 0, oldSize, 0, newSize)
			sqr.y = map(sqr.y, 0, oldSize, 0, newSize)
			sqr.size = map(sqr.size, 0, oldSize, 0, newSize)
		})
	}

	makeGrid () {
		this.baseCells = []
		for (let xi = 0; xi < this._steps; xi++) {
			let row = []
			for (let yi = 0; yi < this._steps; yi++) {
				row.push({ x: xi * this.cellSize, y: yi * this.cellSize, taken: false })
			}
			this.baseCells.push(row)
		}
	}

	makeSquares() {
		this.makeGrid()
		let consecutiveFailures = 0
		let minSize = 3
		let maxSize = 6
		let maxFailures = 10

		this.squares = []
		while (minSize > 1) {
			let sqr = this.maybeFindSquare({ minSize, maxSize, maxTries: 100 })
			if (sqr) {
				this.squares.push(sqr)
				consecutiveFailures = 0
			} else {
				consecutiveFailures++
				if (consecutiveFailures >= maxFailures) {
					minSize--
					maxSize--
					consecutiveFailures = 0
				}
			}
		}

		let lastSquares = []
		this.baseCells.forEach((row) => {
			row.forEach((cell) => {
				if (!cell.taken) {
					lastSquares.push({
						x: cell.x,
						y: cell.y, 
						size: this.cellSize, 
						progress: 0,
						color: random(this.palette),
						duration: 800
					})
				}
			})
		})

		lastSquares = shuffle(lastSquares)
		lastSquares[0].increaseAddSpeed = true
		this.squares.push(...lastSquares)
	}

	maybeFindSquare({ maxTries = 100,currentTry = 0,minSize = 1,maxSize = 5 })  {
		if (currentTry >= maxTries) return

		let choiceX = Math.floor(random(this._steps))
		let choiceY = Math.floor(random(this._steps))
		let squareSizeIdeal = Math.floor(random(minSize, maxSize))
		let squareSize = 1

		let cell = this.baseCells[choiceX][choiceY]
		if (cell.taken) {
			return this.maybeFindSquare({ maxTries, currentTry: currentTry + 1, minSize, maxSize })
		}		

		while (squareSize < squareSizeIdeal) {
			let canExpand = true
			let nextX = choiceX + squareSize
			let nextY = choiceY + squareSize
			if (nextX >= this._steps || nextY >= this._steps) break

			for (let yi = choiceY; yi <= nextY; yi++) {
				let nextCell = this.baseCells[nextX][yi]
				if (nextCell.taken) {
					canExpand = false
					break
				}
			}

			for (let xi = choiceX; xi <= nextX; xi++) {
				var nextCell = this.baseCells[xi][nextY]
				if (nextCell.taken) {
					canExpand = false
					break
				}
			}

			if (canExpand) squareSize++
			else break
		}

		if (squareSize < minSize) {
			return this.maybeFindSquare({ maxTries, currentTry: currentTry + 1, minSize, maxSize })
		}

		for (let xi = choiceX; xi < choiceX + squareSize; xi++) {
			for (let yi = choiceY; yi < choiceY + squareSize; yi++) {
				this.baseCells[xi][yi].taken = true
			}
		}

		return {
			x: cell.x, 
			y: cell.y,
			size: squareSize * this.cellSize,
			progress: 0,
			color: random(this.palette),
			duration: 1500
		}
	}

	drawBase() {
		this.baseCells.forEach((row) => {
			row.forEach((cell) => {
				fill(this.palette[0])
				stroke(this.palette[1]) 
				rect(cell.x, cell.y, this.cellSize) 
			})
		})
	}

	drawSquares() {
		this.squares.forEach((sqr) => this.drawSquare(sqr))
	}

	drawSquare(sqr, useProgress = true) {
		let sz = sqr.size - this.gap
		let cx = sqr.x + sqr.size / 2
		let cy = sqr.y + sqr.size / 2
		if (useProgress) {
			sz *= min(sqr.progress, 1)
		}
		let x = cx - sz / 2
		let y = cy - sz / 2

		fill(sqr.color)
		rect(x, y, sz, sz)
	}

	drawSquaresAnimate(t) {
		if (!this.lastTime) this.lastTime = t 
		if (!this.lastAdd) this.lastAdd = t
		let elapsed = t - this.lastTime 
		this.lastTime = t
		let elapsedSinceAdd = t - this.lastAdd 

		if (elapsedSinceAdd > 1000 / this.addPerSecondCurrent) {
			this.lastAdd = t
			let toDraw = round(elapsedSinceAdd / (1000 / this.addPerSecondCurrent))

			for (let i = 0; i < toDraw; i++) {
				var sqr = this.squares[this.animateIndex]
				if (sqr) {
					this.growing.push(sqr)
					if (sqr.increaseAddSpeed) {
						this.addPerSecondCurrent *= 2
					}
				}
				this.animateIndex++
			}
		}

		noStroke()
		this.growing.forEach((sqr) => {
			sqr.progress += elapsed / sqr.duration
			this.drawSquare(sqr)
		})	

		this.growing = this.growing.filter((sqr) => sqr.progress < 1) 

		if (this.animateIndex >= this.squares.length && this.growing.length === 0) {
			this.resetAnimation() 
			return true
		}

		return false
	}

	resetAnimation() {
		this.animateIndex = 0 
		this.addPerSecondCurrent = this.addPerSecond
		this.lastTime = null 
		this.lastAdd = null
		this.growing = []
	}
}

